  "lib-bmw-m57d30tu2": "euro4", "lib-vw-ea189-20tdi-103kw": "euro5", "lib-toyota-1kd-ftv": "euro3", "lib-toyota-2jz-gte": "euro1",
  "lib-nissan-rb26dett": "euro1", "lib-subaru-ej257": "euro4", "lib-bmw-s65b40": "euro4", "lib-toyota-1kr-fe": "euro4",
