export interface DrivetrainState {
  type: GearboxType;
  /** 0 = neutral, 1 … n. For CVT: 1 while driving. */
  gear: number;
  gearCount: number;
  /** Current gearbox ratio (CVT: continuous). */
  ratio: number;
  finalDrive: number;
  /** DSG: false = Drive (automatic), true = manual tip mode. Manual gearbox: always true. */
  manualMode: boolean;
  shifting: boolean;
  clutch: number;
  speedKmh: number;
  maxSpeedKmh: number;
  /** Stopwatch 0–100 km/h: running time and last result. */
  t0to100S: number | null;
  t0to100Running: number | null;
  /** Electronic top-speed governor (issue #32): limit in km/h, null = off ("Aufhebung"). */
  speedLimitKmh: number | null;
  /** True while the governor holds the pedal back ("abgeregelt"). */
  limiting: boolean;
  /** True when the recorded maxSpeedKmh was reached with the governor in control. */
  maxSpeedLimited: boolean;
  /** Motorcycle: drive force at the wheelie limit, anti-wheelie is cutting (issue #25). */
  wheelie: boolean;
  /** Issue #22: driven wheels spin (held ≥ 0.3 s for the display), brakes locked, tyre tread temperature °C,
   *  current peak μ (tyre × surface × temperature), rated speed of the fitted tyre (speed index) in km/h. */
  wheelSpin: boolean;
  wheelsLocked: boolean;
  tyreTempC: number;
  grip: number;
  tyreRatingKmh: number;
  /**
   * Issue #23 (optional for older consumers): assistant settings, interventions (held ASSIST_LAMP_HOLD_S for the
   * blinking lamps), launch control armed, black-ice warning (< +3 °C), aquaplaning (water film costs > 10 % grip).
   */
  assists?: AssistSettings;
  absActive?: boolean;
  asrActive?: boolean;
  espActive?: boolean;
  launchArmed?: boolean;
  iceWarning?: boolean;
  aquaplaning?: boolean;
  /** Issue #30: cruise control and driver speed limiter (optional for older consumers). */
  cruise?: Readonly<CruiseState>;
  /**
   * Issue #48: position along the route (m), and the gradient (%) and altitude (m) the car is on – from the
   * route profile, or the fixed values of the environment on terrain "static".
   */
  positionM?: number;
  roadGradePct?: number;
  roadAltitudeM?: number;
  /**
   * Issue #91: parking brake applied (by Auto-Hold or by hand) and the Auto-Hold function switched on. Optional for
   * older consumers; the Drivetrain always sets both.
   */
  parkingBrake?: boolean;
  autoHold?: boolean;
  /**
   * Issue #53 (optional for older consumers; the Drivetrain always sets them): gearbox oil temperature °C (motorcycle:
   * shared sump = engine oil), above the warning threshold, TCU protection mode (pedal limited), oil ageing / damage
   * 0 … 1 and gearbox failed (realism "real" only: no drive until reset). docs/research/vehicle.md §8.
   */
  gearboxOilC?: number;
  gearboxOilWarn?: boolean;
  gearboxProtect?: boolean;
  gearboxWear?: number;
  gearboxFailed?: boolean;
  /** Issue #108: an electric car is loaded (CarSetup.ev). */
  electric?: boolean;
  /**
   * Issue #144 (optional for older consumers; the Drivetrain always sets them): hot-zone temperature of the most
   * loaded tyre °C, overheating warning, damage 0 … 1, vibration stage (grip reduced) and tyre failed (blowout /
   * tread separation, realism "real" only, until Drivetrain.repairTyres). docs/research/vehicle.md §11.
   */
  tyreCarcassC?: number;
  tyreWarn?: boolean;
  tyreDamage?: number;
  tyreVibration?: boolean;
  tyreFailed?: boolean;
  /**
   * Issue #149: hottest zone of the tyre for the tyre field/gauge, °C: the #144 hot zone, or the tread surface heated
   * by slip (burnout, locked-wheel skid) when that is hotter. Tread worn by slip 0 … 1 (also in tyreDamage) and the
   * "Lauffläche überhitzt" flag (also in tyreWarn).
   */
  tyreHotC?: number;
  tyreWear?: number;
  tyreTreadHot?: boolean;
}

