const GEARBOX_PROTECT_PEDAL = 0.5;

/** A complete vehicle setup (issue #22, src/data/vehicle-library.ts): kind, body, tyre, gearbox, governor. */
export interface CarSetup {
  /** Vehicle kind (issue #25); default "car". */
  kind?: VehicleKind;
  /** Tank volume in litres (manufacturer data); default DEFAULT_TANK_L of the kind. */
  tankL?: number;
  /**
   * Commercial vehicles (issue #31): permissible gross mass in kg. vehicle.massKg is then the EMPTY mass incl. driver
   * and the load (setLoad, 0 = leer … 1 = voll) moves the simulated mass between the two. Unset = no load control.
   */
  fullMassKg?: number;
  /** Initial load share 0 … 1 (issue #31), default 1 (fully loaded, the hard case). */
  loadShare?: number;
  /** Body/chassis; wheel radius and rolling resistance are overwritten from the tyre. */
  vehicle: VehicleParams;
  tyre: TyreSetup;
  gearbox: GearboxType;
  /** Gear ratios of this car; default GEARBOXES[gearbox]. */
  gearboxSpec?: GearboxSpec;
  speedLimitKmh: number | null;
  /** Electric car (issue #108): motors, battery, reduction. `gearbox`/`gearboxSpec` are then ignored by the drivetrain. */
  ev?: EvConfig;
  /**
   * Hybrid (issue #157): with `ev` (motors, battery) and the car's library engine. The drivetrain runs the electric path
   * (the HybridSimulator couples the engine); `gearbox`/`gearboxSpec`/`tankL` describe the engine side.
   */
  hybrid?: HybridConfig;
}

/**
 * A drive that fits any vehicle body (issue #154): a combustion engine with its gearbox and tank, or electric motors
 * with battery and inverter. Both may be set later for a hybrid (#157). `extraKg`: parts the configs do not carry
 * (E-Tuner cooling, axial-flux motors, carbon sleeves; src/data/ev-tuning.ts deltaKg).
 * The body is a CarSetup whose mass is the mass without drive; src/data/drive-swap.ts puts the two together.
 */
export interface DriveSpec {
  /** refWheelRadiusM: the wheel the gearbox ratios were made for (donor car); default the new body's wheel. */
  engine?: { config: EngineConfig; gearbox: GearboxType; gearboxSpec: GearboxSpec; tankL: number; refWheelRadiusM?: number };
  ev?: EvConfig;
  /** Hybrid (issue #157): `engine` and `ev` both set. */
  hybrid?: HybridConfig;
  extraKg?: number;
}

