export const SPEED_LIMIT_OPTIONS: readonly (number | null)[] = [null, 80, 85, 90, 100, 180, 210, 250, 270, 300];
export const DEFAULT_SPEED_LIMIT_KMH = 250;
/** Tyre speed rating W (ETRTO / ECE-R 30): 270 km/h. Since #22 the fitted tyre's index is in state.tyreRatingKmh. */
export const TYRE_RATING_W_KMH = 270;
/** Default ambient for the tyre temperature model, °C (issue #23: follows Environment.ambientC). */
const TYRE_AMBIENT_C = DEFAULT_ENVIRONMENT.ambientC;

// Governor PI gains (issue #32). It takes over from (limit − 5 km/h) and trims the pedal so speed settles at the
// limit without the hard cut of a rev limiter, like an ECU top-speed limiter acting on throttle / injection.
const GOV_WINDOW_KMH = 5;
const GOV_KP = 0.12; // pedal per km/h of remaining margin
const GOV_KI = 0.06; // pedal per (km/h · s)

const RAD_TO_RPM = 30 / Math.PI;

/** Max. rate of the air altitude (m/s), see updateRoad (#48). Fast real climbs reach ≈ 5 m/s. */
const AIR_ALT_RATE = 50;

export class Drivetrain {
  private st: DrivetrainState;
  private shiftT = 0;
  private pendingGear = 0;
  private holdLaunch = 0;
  /** Pedal cap holding the launch speed while the clutch is dosed by traction (review PR #37). */
  private launchCap = 1;
  private gearDwell = 0;
  private lastSpeedMs = 0;
  /** Fuel tank of the vehicle (drained by the app from the engine's fuel flow on the chassis dyno). */
  readonly tank = new FuelTank(DEFAULT_TANK_L.car);
  /** Issue #48: distance along the route and the road there (gradient, altitude). */
  private positionM = 0;
  private road = { altitudeM: 0, gradePct: 0 };
  private airAltM = 0;
  private govActive = false;
  private govI = 0;
  private govCap = 1;
  /** Remembered integrator (hold pedal) for the current limit, null = none yet. */
  private govHold: number | null = null;
  private shiftDir: 1 | -1 = 1;
  private wheelieHold = 0;
  /** Current vehicle preset (issue #25). */
  kind: VehicleKind = "car";
  /** Load control (issue #31): empty / gross mass, null = none. */
  private emptyKg = DEFAULT_VEHICLE.massKg;
  private fullKg: number | null = null;
  private loadSh = 0;
  /** Limiter of the car/motorcycle before a truck/bus was loaded (review PR #82). */
  private carLimitKmh: number | null = DEFAULT_SPEED_LIMIT_KMH;
  /** Gear ratios in use (GEARBOXES[type] or a car's own, issue #22). */
  private spec: GearboxSpec;
  private tyreSetup: TyreSetup = DEFAULT_TYRE;
  private surfaceKind: RoadSurface = "dry";
  private gripFactor = 1;
  private spinHold = 0;
  private tyreT = TYRE_AMBIENT_C;
  /** Tyre heat and damage (issue #144, tyre-heat.ts). */
  private tyreHeatC = TYRE_AMBIENT_C;
  private tyreDmg = 0;
  private tyreWarnOn = false;
  private tyreBlown = false;
  /** Slip heat of the hottest driven tyre (issue #149, tyre-heat.ts stepTyreSlipHeat). */
  private slipHeat: TyreSlipHeat = { ...NO_SLIP_HEAT };
  private treadHotOn = false;
  private env: Environment = { ...DEFAULT_ENVIRONMENT };
  private aquaplane = false;
  private assistSet: AssistSettings = { ...DEFAULT_ASSISTS };
  /** Assistant choice of the car while a motorcycle is loaded (restored on the way back). */
  private carAssists: AssistSettings = { ...DEFAULT_ASSISTS };
  private tc = new TractionControl();
  private tcOut = { pedalCap: 1, torqueCut: 0, pedalFloor: 0 };
  private absHold = 0;
  private asrHold = 0;
  private espHold = 0;
  private roadKmh = 0;
  private lastEffPedal = 0;
  private tcCutting = false;
  /** Cruise control and driver speed limiter (issue #30). */
  private cc = new CruiseControl();
  private ccDownT = 0;
  /** Full-load torque at a converter's stall speed, per stall rpm (issue #14). */
  private stallTorque = new Map<number, number>();
  /** Lock-up clutch of the converter automatic 0 … 1 (issue #14). */
  private lockup = 0;
  /** Engine speed of the last frame (manual downshift blip, issue #14). */
  private lastRpm = 0;
  /** Auto-Hold function on (issue #91, setting "Auto-Hold", default on). */
  private autoHoldOn = true;
  /** Released by hand: Auto-Hold waits for a fresh brake press, drive-away or > AUTO_HOLD_MAX_KMH. */
  private holdSuppressed = false;
  private lastBrake = 0;
  /** Gearbox oil (issue #53): temperature (NaN = not yet initialised after a reset), wear, flags, settings. */
  private gbOilC = Number.NaN;
  private gbWear = 0;
  private gbWarn = false;
  private gbProtect = false;
  private gbFailed = false;
  private gbCooler = true;
  /** Aftermarket air-to-oil cooler, W/K at 25 m/s (0 = none, #100 addendum). */
  private gbAuxCoolerWK = 0;
  private damageLevel: NonNullable<SimInputs["damage"]> = "real";
  /** Electric car loaded (issue #108). */
  private evCfg: EvConfig | null = null;
  private hyCfg: HybridConfig | null = null;

  constructor(
    private cfg: EngineConfig,
    private summary: EngineSummary,
    type: GearboxType = "manual",
    public vehicle: VehicleParams = DEFAULT_VEHICLE,
  ) {
    this.spec = GEARBOXES[type];
    this.st = this.fresh(type, GEARBOXES[type].finalDrive, DEFAULT_SPEED_LIMIT_KMH);
    this.updateRoad();
  }

  private fresh(type: GearboxType, finalDrive: number, speedLimitKmh: number | null): DrivetrainState {
    const g = this.spec;
    return {
      type, gear: 1, gearCount: this.evCfg || type === "cvt" ? 1 : g.ratios.length,
      ratio: this.evCfg ? 1 : g.ratios[0]!, finalDrive, manualMode: !this.evCfg && type === "manual", shifting: false, clutch: 0,
      speedKmh: 0, maxSpeedKmh: 0, t0to100S: null, t0to100Running: null,
      speedLimitKmh, limiting: false, maxSpeedLimited: false, wheelie: false,
      wheelSpin: false, wheelsLocked: false, tyreTempC: this.tyreT, grip: this.currentGrip(),
      tyreRatingKmh: speedRatingKmh(this.tyreSetup.speedIndex),
      assists: { ...this.assistSet }, absActive: false, asrActive: false, espActive: false, launchArmed: false,
      iceWarning: iceWarning(this.env.ambientC), aquaplaning: false, cruise: this.cc.state,
      parkingBrake: false, autoHold: this.autoHoldOn,
      gearboxOilC: Number.isFinite(this.gbOilC) ? this.gbOilC : this.env.ambientC, gearboxOilWarn: this.gbWarn,
      gearboxProtect: this.gbProtect, gearboxWear: this.gbWear, gearboxFailed: this.gbFailed,
      electric: !!this.evCfg,
      tyreCarcassC: this.tyreHeatC, tyreHotC: this.tyreHeatC, tyreWarn: this.tyreWarnOn || this.tyreBlown, tyreDamage: this.tyreDmg,
      tyreVibration: this.tyreDmg > TYRE_HEAT.vibrationAt && !this.tyreBlown, tyreFailed: this.tyreBlown,
    };
  }

  /** Electric car configuration (issue #108), null for a combustion car. */
  get ev(): Readonly<EvConfig> | null {
    return this.evCfg;
  }

  /** Hybrid configuration (issue #157), null otherwise; `ev` holds its motors and battery. */
  get hybrid(): Readonly<HybridConfig> | null {
    return this.hyCfg;
  }

  /**
   * Another electric configuration for the loaded electric car (tuning, issue #108), only at standstill. The mass
   * change of motors and battery is set by the caller with setVehicleParams.
   */
  setEv(ev: EvConfig): boolean {
    if (!this.evCfg || this.st.speedKmh > 0.5) return false;
    this.evCfg = structuredClone(ev);
    this.st.finalDrive = evRefRatio(this.evCfg);
    return true;
  }

  get state(): DrivetrainState {
    return this.st;
  }

  setEngine(cfg: EngineConfig, summary: EngineSummary) {
    this.cfg = cfg;
    this.summary = summary;
    this.stallTorque.clear();
  }

  setType(type: GearboxType) {
    // an electric car has its fixed reduction (issue #108)
    if (this.evCfg) return;
    this.clearTransient();
    this.resetGearboxOil();
    this.spec = GEARBOXES[type];
    Object.assign(this.st, this.fresh(type, GEARBOXES[type].finalDrive, this.st.speedLimitKmh));
  }

  /** Gear ratios in use (generic per type or the loaded car's own). */
  get gearbox(): Readonly<GearboxSpec> {
    return this.spec;
  }

  /**
   * Own gear ratios (issue #14): count and single ratios, checked by validateRatios(). Only at standstill; the vehicle
   * starts again in 1st gear. Not for the CVT (its two values are the ratio range). Returns null when applied, else
   * the reason (German, for the UI).
   */
  setRatios(ratios: readonly number[]): string | null {
    if (this.evCfg) return "Das Elektroauto hat ein festes 1-Gang-Untersetzungsgetriebe";
    if (this.st.type === "cvt") return "Das CVT hat keine Gänge";
    if (!this.ratiosEditable) return "Nur im Stand (Handbremse) oder in N";
    const err = validateRatios(ratios);
    if (err) return err;
    const neutral = this.st.gear === 0;
    this.clearTransient();
    this.spec = { ...this.spec, ratios: [...ratios] };
    // in N (also rolling) the gearbox stays in N; at standstill it starts again in 1st gear
    Object.assign(this.st, { gear: neutral ? 0 : 1, gearCount: ratios.length, ratio: ratios[0]!, shifting: false });
    return null;
  }

  /**
   * Gear ratios can be changed (issue #14, review PR #90): not on the CVT; at standstill (≤ 0.5 km/h – a converter
   * automatic creeping in D stops when the brake is held), with the parking brake applied (issue #91) or in N, also
   * while rolling.
   */
  get ratiosEditable(): boolean {
    const s = this.st;
    return s.type !== "cvt" && (s.speedKmh <= 0.5 || !!s.parkingBrake || (s.gear === 0 && !s.shifting));
  }

  /** Auto-Hold on/off (issue #91). Switching it off does not release a brake that is applied. */
  setAutoHold(on: boolean) {
    if (on === this.autoHoldOn) return;
    this.autoHoldOn = on;
    this.st.autoHold = on;
    this.holdSuppressed = false;
  }

  get autoHoldEnabled(): boolean {
    return this.autoHoldOn;
  }

  /**
   * Parking brake by hand (issue #91, P button): applied at any speed (a rolling car is braked); released, Auto-Hold
   * does not grab again until the brake is pressed anew, the car drives off or exceeds AUTO_HOLD_MAX_KMH.
   */
  setParkingBrake(on: boolean) {
    this.st.parkingBrake = on;
    this.holdSuppressed = !on;
  }

  /** Toggles the parking brake by hand; returns the new state. */
  toggleParkingBrake(): boolean {
    this.setParkingBrake(!this.st.parkingBrake);
    return !!this.st.parkingBrake;
  }

  /**
   * Auto-Hold / drive-away (issue #91, parking-brake.ts, docs/research/vehicle.md §7), from the last frame's speed:
   * releases on throttle with a gear engaged and the engine running (or a biting clutch); engages at walking pace
   * without throttle when braking, engine off, in N or stopped.
   */
  private updateHold(vRoadMs: number, pedal: number, brake: number, engine: EngineState) {
    const s = this.st;
    const kmh = vRoadMs * 3.6;
    const geared = s.gear > 0 && engine.running;
    // drive-away only from (near) standstill: P pressed while rolling keeps braking, even with the gear in, the clutch
    // closed or the throttle open (review PR #92); the clutch counts only once the held car stands
    const away = kmh <= AUTO_HOLD_MAX_KMH && (pedal > HOLD_RELEASE_PEDAL || (vRoadMs < 0.1 && s.clutch > 0.1 && s.type !== "automatic"));
    if (s.parkingBrake && geared && away) s.parkingBrake = false;
    if (this.holdSuppressed && ((brake > 0.05 && this.lastBrake <= 0.05) || kmh > AUTO_HOLD_MAX_KMH || (geared && pedal > HOLD_RELEASE_PEDAL))) this.holdSuppressed = false;
    this.lastBrake = brake;
    if (!s.parkingBrake && this.autoHoldOn && !this.holdSuppressed && autoHoldEngages({ speedKmh: kmh, pedal, brake, running: engine.running, gear: s.gear })) s.parkingBrake = true;
  }

  get tyre(): TyreSetup {
    return this.tyreSetup;
  }

  get surface(): RoadSurface {
    return this.surfaceKind;
  }

  /** Body/chassis parameters (mass, cW, A, layout, weight share, CG, wheelbase); a fresh object each time. */
  setVehicleParams(p: Partial<VehicleParams>) {
    this.vehicle = withTyre({ ...this.vehicle, ...p }, this.tyreSetup);
    // a typed-in mass of a truck/bus moves the load share (and widens empty/gross if it lies outside, issue #31)
    if (this.fullKg !== null && p.massKg !== undefined && Number.isFinite(p.massKg)) {
      this.emptyKg = Math.min(this.emptyKg, p.massKg);
      this.fullKg = Math.max(this.fullKg, p.massKg);
      this.loadSh = this.fullKg > this.emptyKg ? (p.massKg - this.emptyKg) / (this.fullKg - this.emptyKg) : 0;
    }
    this.refreshTyreState();
  }

  /** Tyre type, size and speed index: wheel radius, rolling resistance, μ and tyre rating follow (issue #22). */
  setTyre(t: TyreSetup) {
    this.tyreSetup = { type: t.type, size: { ...t.size }, speedIndex: t.speedIndex };
    this.vehicle = withTyre(this.vehicle, this.tyreSetup);
    this.refreshTyreState();
  }

  /**
   * Road surface and an extra grip factor (issue #23 hooks: wetness, snow, ice; factor e.g. for a water film).
   * μ = tyreGrip(type, surface, tyreTemp) × factor.
   */
  setSurface(surface: RoadSurface, factor = 1) {
    this.surfaceKind = surface;
    this.gripFactor = Math.max(0, factor);
    this.refreshTyreState();
  }

  /**
   * Environment (issue #23): weather → surface and water film, outside temperature (tyres; the simulator gets it via
   * simInputs()), altitude (air pressure and density), gradient %. Partial updates are merged.
   */
  setEnvironment(e: Partial<Environment>) {
    const n = { ...this.env, ...e };
    n.ambientC = Math.min(50, Math.max(-30, Number.isFinite(n.ambientC) ? n.ambientC : 20));
    n.altitudeM = Math.min(5000, Math.max(-400, Number.isFinite(n.altitudeM) ? n.altitudeM : 0));
    n.gradePct = Math.min(30, Math.max(-30, Number.isFinite(n.gradePct) ? n.gradePct : 0));
    n.terrain = isTerrain(n.terrain) ? n.terrain : "static";
    // a new route starts at its beginning
    if (n.terrain !== (this.env.terrain ?? "static")) this.positionM = 0;
    this.env = n;
    this.updateRoad();
    const w = weatherSurface(n.weather);
    this.surfaceKind = w.surface;
    this.gripFactor = w.factor;
    this.aquaplane = w.aquaplaning;
    this.refreshTyreState();
    this.st.iceWarning = iceWarning(n.ambientC);
  }

  get environment(): Readonly<Environment> {
    return this.env;
  }

  /** ambientC / ambientKpa for SimInputs (engine intake air) from the environment (altitude of the road, #48). */
  simInputs(): { ambientC: number; ambientKpa: number } {
    return { ambientC: this.env.ambientC, ambientKpa: altitudeToKpa(this.airAltM) };
  }

  /** Position along the route (#48), e.g. to start over. */
  setPosition(m: number) {
    this.positionM = Number.isFinite(m) ? m : 0;
    this.updateRoad();
  }

  /**
   * Road at the current position. The altitude used for the air (pressure, density) follows the road altitude at
   * most AIR_ALT_RATE m/s: where a ramp route starts over ("Berg hoch/runter", next mountain) the air changes over
   * half a minute instead of in one frame (no torque jump in the engine). dt = 0: set directly (new route/setting).
   */
  private updateRoad(dt = 0) {
    this.road = roadAt(this.env, this.positionM);
    const target = this.road.altitudeM;
    this.airAltM = dt > 0 ? this.airAltM + Math.max(-AIR_ALT_RATE * dt, Math.min(AIR_ALT_RATE * dt, target - this.airAltM)) : target;
    this.st.positionM = this.positionM;
    this.st.roadGradePct = this.road.gradePct;
    this.st.roadAltitudeM = this.road.altitudeM;
  }

  /** Driver assistance on/off (issue #23), partial updates merged. */
  setAssists(a: Partial<AssistSettings>) {
    this.assistSet = { ...this.assistSet, ...a };
    this.st.assists = { ...this.assistSet };
    if (!this.assistSet.asr) this.tc.reset();
  }

  get assists(): Readonly<AssistSettings> {
    return this.assistSet;
  }

  /** Loads a complete car (issue #22): body, tyre, gearbox incl. its own ratios, governor. Vehicle at standstill. */
  applyCar(car: CarSetup) {
    // another car starts at the beginning of the route (#48)
    this.positionM = 0;
    this.updateRoad();
    const wasCar = !isMotorcycleKind(this.kind);
    // leaving a car/bike for a truck/bus: remember its limiter, setVehicle restores it on the way back (review PR #82)
    if (!isCommercialKind(this.kind) && isCommercialKind(car.kind ?? "car") && this.st) this.carLimitKmh = this.st.speedLimitKmh;
    this.kind = car.kind ?? "car";
    // the car's own tank, full
    this.tank.setCapacity(car.tankL ?? DEFAULT_TANK_L[this.kind]);
    // motorcycles (issue #25 presets: CBR1000RR-class superbike, tourer) have ABS but no ESP; traction control is
    // off like on the non-electronic base bikes the presets are modelled on (issue #23 decision). The car's own
    // choice is remembered and comes back when a car is loaded again (review PR #39).
    if (isMotorcycleKind(this.kind)) {
      if (wasCar) this.carAssists = { ...this.assistSet };
      this.setAssists({ asr: false, esp: false });
    } else if (!wasCar) this.setAssists({ ...this.carAssists });
    this.tyreSetup = { type: car.tyre.type, size: { ...car.tyre.size }, speedIndex: car.tyre.speedIndex };
    this.vehicle = withTyre({ ...car.vehicle }, this.tyreSetup);
    // load (issue #31): empty mass from the setup, gross mass for "voll"
    this.emptyKg = car.vehicle.massKg;
    this.fullKg = car.fullMassKg !== undefined && car.fullMassKg > car.vehicle.massKg ? car.fullMassKg : null;
    this.loadSh = this.fullKg === null ? 0 : Math.min(1, Math.max(0, car.loadShare ?? 1));
    if (this.fullKg !== null) this.vehicle.massKg = this.emptyKg + this.loadSh * (this.fullKg - this.emptyKg);
    this.tyreT = this.env.ambientC;
    this.clearTransient();
    this.resetGearboxOil();
    this.repairTyres();
    this.spec = car.gearboxSpec ? { ...car.gearboxSpec, ratios: [...car.gearboxSpec.ratios] } : GEARBOXES[car.gearbox];
    // electric car (issue #108): one fixed ratio (the reference motor's reduction), see evInputs()
    this.evCfg = car.ev ? structuredClone(car.ev) : null;
    this.hyCfg = car.ev && car.hybrid ? structuredClone(car.hybrid) : null;
    if (this.evCfg) this.spec = { ratios: [1], finalDrive: evRefRatio(this.evCfg), efficiency: this.evCfg.gearEfficiency, shiftTimeS: 0 };
    Object.assign(this.st, this.fresh(car.gearbox, this.spec.finalDrive, car.speedLimitKmh), { maxSpeedKmh: 0, t0to100S: null });
    this.t100Armed = false;
    this.t100LiftS = 0;
  }

  /** μ = tyre × surface × tread temperature × user/water-film factor × compound window × aquaplaning (issue #23). */
  private currentGrip(): number {
    const t = this.tyreSetup.type;
    const aq = this.aquaplane ? aquaplaningFactor(t, this.roadKmh, this.tyreSetup.size.widthMm) : 1;
    return tyreGrip(t, this.surfaceKind, this.treadC()) * this.gripFactor * compoundFactor(t, this.env.ambientC, this.surfaceKind) * aq
      * tyreGripFactor(this.tyreDamageAll(), this.tyreBlown, this.tyreClass());
  }

  /** Tread temperature for the grip: the rolling model (tyres.ts) plus the slip heat (issue #149). */
  private treadC(): number {
    return this.tyreT + this.slipHeat.treadK;
  }

  /** Damage for the grip/vibration stages: carcass reversion (#144) or tread worn by slip (#149), whichever is further. */
  private tyreDamageAll(): number {
    return Math.max(this.tyreDmg, this.slipHeat.wear);
  }

  private refreshTyreState() {
    if (!this.st) return;
    this.st.grip = this.currentGrip();
    this.st.tyreRatingKmh = speedRatingKmh(this.tyreSetup.speedIndex);
    this.st.tyreTempC = this.treadC();
  }

  /** Top-speed governor in km/h; null (or ≤ 0) switches it off ("Aufhebung"). */
  setSpeedLimit(kmh: number | null) {
    this.st.speedLimitKmh = kmh !== null && kmh > 0 ? kmh : null;
    this.resetGovernor();
  }

  /** Vehicle preset: sets mass/aero/wheel, the default gearbox and final drive of that vehicle (issue #25). */
  setVehicle(kind: VehicleKind) {
    const p = VEHICLES[kind];
    // commercial presets bring their own limiter (EU 92/6/EEC); back from a truck/bus the car's previous limiter returns
    const limit = p.speedLimitKmh ?? (isCommercialKind(this.kind) ? this.carLimitKmh : this.st.speedLimitKmh);
    this.applyCar({
      kind, vehicle: p.params, tyre: p.tyre, gearbox: p.gearboxes[0]!,
      gearboxSpec: { ...(p.gearboxSpec ?? GEARBOXES[p.gearboxes[0]!]), finalDrive: p.finalDrive }, speedLimitKmh: limit,
      fullMassKg: p.fullMassKg,
    });
  }

  /**
   * Load of a commercial vehicle (issue #31): share 0 (leer) … 1 (voll); mass = empty + share·(gross − empty).
   * Null for vehicles without load control. Only at standstill (like the other vehicle settings in the UI).
   */
  get load(): { share: number; emptyKg: number; fullKg: number } | null {
    return this.fullKg === null ? null : { share: this.loadSh, emptyKg: this.emptyKg, fullKg: this.fullKg };
  }

  setLoad(share: number) {
    if (this.fullKg === null || !Number.isFinite(share)) return;
    this.loadSh = Math.min(1, Math.max(0, share));
    this.vehicle = { ...this.vehicle, massKg: this.emptyKg + this.loadSh * (this.fullKg - this.emptyKg) };
  }

  /** Final drive ratio ("Achsübersetzung"): shorter = more pull, lower top speed. */
  setFinalDrive(fd: number) {
    this.st.finalDrive = Math.min(6, Math.max(2, fd));
  }

  /** Vehicle back to standstill, first gear, records kept. */
  reset() {
    const keep = { maxSpeedKmh: this.st.maxSpeedKmh, t0to100S: this.st.t0to100S, maxSpeedLimited: this.st.maxSpeedLimited };
    this.clearTransient();
    this.resetGearboxOil();
    this.repairTyres();
    Object.assign(this.st, this.fresh(this.st.type, this.st.finalDrive, this.st.speedLimitKmh), keep);
    this.positionM = 0;
    this.updateRoad();
  }

  /**
   * Gearbox oil back to its start (issue #53): the temperature is set on the first frame the engine has run after
   * this, warm (GEARBOX_WARM_C, at most the coolant) when the engine started warm ("Motor warm starten"), otherwise
   * at the outside temperature (vehicle.md §8). Wear and failure are cleared.
   */
  private resetGearboxOil() {
    this.gbOilC = Number.NaN;
    this.gbWear = 0;
    this.gbWarn = false;
    this.gbProtect = false;
    this.gbFailed = false;
  }

  /**
   * "Reifen wechseln/reparieren" (issue #144): new tyres at the outside temperature, no damage. Like refuelling the
   * UI offers it at standstill; reset() and applyCar() do it too.
   */
  repairTyres() {
    this.tyreHeatC = this.env.ambientC;
    this.tyreDmg = 0;
    this.tyreWarnOn = false;
    this.tyreBlown = false;
    this.tyreT = this.env.ambientC;
    this.slipHeat = { ...NO_SLIP_HEAT };
    this.treadHotOn = false;
    if (!this.st) return;
    Object.assign(this.st, {
      tyreCarcassC: this.tyreHeatC, tyreHotC: this.tyreHeatC, tyreWarn: false, tyreDamage: 0, tyreWear: 0, tyreTreadHot: false,
      tyreVibration: false, tyreFailed: false, tyreTempC: this.treadC(),
    });
    this.st.grip = this.currentGrip();
  }

  private tyreClass(): TyreHeatClass {
    return isMotorcycleKind(this.kind) ? "motorcycle" : isCommercialKind(this.kind) ? "commercial" : "car";
  }

  /**
   * Tyre hot zone, warning and damage (issue #144, tyre-heat.ts, vehicle.md §11). Load relative to the vehicle's
   * design mass (gross mass of trucks/buses); inflation at its nominal value. Damage per realism level: "real" up to
   * the blowout, "lenient" stops just before it (warning and grip loss only), "off" none.
   */
  private stepTyres(dt: number, vRoad: number, frictionW = 0, sliding = false, locked = false) {
    const s = this.st;
    const ref = this.fullKg ?? this.emptyKg;
    const load = ref > 0 ? this.vehicle.massKg / ref : 1;
    const v = Number.isFinite(vRoad) ? Math.abs(vRoad) : 0;
    this.tyreHeatC = stepTyreHeat(this.tyreHeatC, dt, v * 3.6, s.tyreRatingKmh, this.env.ambientC, load);
    // slip heat (issue #149): tread surface and carcass of the hottest tyre; the tread wears with the friction energy
    const wearBefore = this.slipHeat.wear;
    this.slipHeat = stepTyreSlipHeat(this.slipHeat, dt, frictionW, this.tyreSetup.size.widthMm, this.vehicle.wheelRadiusM, this.treadC(), sliding, locked);
    if (this.damageLevel === "off" || this.tyreBlown) this.slipHeat.wear = wearBefore;
    else if (this.damageLevel === "lenient") this.slipHeat.wear = Math.min(0.99, this.slipHeat.wear);
    const T = this.tyreHeatC + this.slipHeat.carcassK;
    const hot = this.tyreHeatC + this.slipHeat.treadK;
    this.tyreWarnOn = this.tyreWarnOn ? T >= TYRE_HEAT.warnC - TYRE_HEAT.hystK : T >= TYRE_HEAT.warnC;
    this.treadHotOn = this.treadHotOn ? hot >= TYRE_SLIP.warnC - TYRE_HEAT.hystK : hot >= TYRE_SLIP.warnC;
    if (this.damageLevel !== "off" && !this.tyreBlown) {
      this.tyreDmg = Math.min(this.damageLevel === "lenient" ? 0.99 : 1, this.tyreDmg + tyreDamageRate(T) * dt);
      if (this.damageLevel === "real" && this.tyreDamageAll() >= 1) this.tyreBlown = true;
    }
    const dmg = this.tyreDamageAll();
    Object.assign(s, {
      tyreCarcassC: T, tyreHotC: Math.max(T, hot), tyreWarn: this.tyreWarnOn || this.treadHotOn || this.tyreBlown, tyreDamage: this.tyreDmg,
      tyreWear: this.slipHeat.wear, tyreTreadHot: this.treadHotOn,
      tyreVibration: dmg > TYRE_HEAT.vibrationAt && !this.tyreBlown, tyreFailed: this.tyreBlown,
    });
  }

  /**
   * Friction power at the hottest tyre, W (issue #149, vehicle.md §12): spinning driven wheels F_x·|v_wheel − v| shared by
   * the driven tyres; locked wheels slide with the road speed, braked: ≈ 0.9·μ·m·g over all tyres (sliding friction).
   */
  private slipFrictionW(engine: EngineState, v: number, vRoad: number, brake: number, mu: number): number {
    if (!Number.isFinite(v) || !Number.isFinite(vRoad)) return 0;
    const moto = isMotorcycleKind(this.kind);
    const commercial = isCommercialKind(this.kind);
    const nAll = moto ? 2 : commercial ? 6 : 4;
    const nDriven = moto ? 1 : this.vehicle.driveLayout === "awd" ? 4 : commercial ? 4 : 2;
    const fx = Math.abs(engine.tyreForceN ?? 0);
    if (engine.wheelsLocked) {
      const braked = 0.9 * mu * this.vehicle.massKg * 9.81 * Math.min(1, Math.max(0, brake)) / nAll;
      return Math.abs(vRoad) * Math.max(fx / nDriven, braked);
    }
    return (fx / nDriven) * Math.abs(v - vRoad);
  }

  /** Body for the simulator: a failed tyre adds its rolling resistance (issue #144, tyre-heat.ts blowoutRollingExtra). */
  private couplingVehicle(vRoad: number): VehicleParams {
    if (!this.tyreBlown) return this.vehicle;
    const v = Number.isFinite(vRoad) ? vRoad : 0;
    return { ...this.vehicle, rollingResistance: this.vehicle.rollingResistance + blowoutRollingExtra(v, this.tyreClass()) };
  }

  /** Realism level of the damage model (issue #53, same levels as SimInputs.damage, issue #66). */
  setDamageLevel(level: SimInputs["damage"]) {
    this.damageLevel = level ?? "real";
    if (this.damageLevel !== "real") this.tyreBlown = false;
    if (this.damageLevel === "off") this.tyreDmg = 0;
    if (this.damageLevel === "lenient") this.tyreDmg = Math.min(this.tyreDmg, 0.99);
    if (this.damageLevel === "off") this.gbProtect = false;
    if (this.damageLevel !== "real") this.gbFailed = false;
    if (this.damageLevel === "lenient") this.gbWear = Math.min(this.gbWear, 0.99);
  }

  /** Optional gearbox oil cooler (issue #53): on by default; only gearboxes with one in their spec are affected. */
  setGearboxCooler(on: boolean) {
    this.gbCooler = on;
  }

  get gearboxCooler(): boolean {
    return this.gbCooler;
  }

  /** Aftermarket air-to-oil gearbox cooler (#100 addendum, vehicle.md §8 [B19]): UA in W/K at 25 m/s, 0 = none. */
  setGearboxAuxCooler(wk: number) {
    this.gbAuxCoolerWK = Number.isFinite(wk) ? Math.max(0, wk) : 0;
  }

  get gearboxAuxCoolerWK(): number {
    return this.gbAuxCoolerWK;
  }

  /**
   * Gearbox oil temperature, warning, protection mode and damage (issue #53, gearbox-thermal.ts, vehicle.md §8).
   * Heat from (1 − η)·P through the gear set, churning, clutch slip (wet: all, dry: share) and converter slip
   * T_P·ω_P − T_T·ω_T (vehicle.md §4).
   */
  private stepGearboxOil(dt: number, engine: EngineState, clutch: number, inputRpm: number, outputRpm: number, converter: ConverterCoupling | undefined, vRoad: number) {
    const s = this.st;
    const spec = GEARBOX_THERMAL[gearboxThermalKind(s.type, this.kind)];
    const ambient = this.env.ambientC;
    if (spec.sharedSump) {
      // motorcycle: the gearbox runs in the engine oil; the engine's own limits and warnings cover it
      this.gbOilC = Number.isFinite(engine.oilC) ? engine.oilC : ambient;
      Object.assign(s, { gearboxOilC: this.gbOilC, gearboxOilWarn: false, gearboxProtect: false, gearboxWear: 0, gearboxFailed: false });
      return;
    }
    if (!Number.isFinite(this.gbOilC)) {
      // the simulator applies "Motor warm starten" on its first step after a reset (SimInputs.startWarm)
      if (!(engine.t > 0)) {
        s.gearboxOilC = ambient;
        return;
      }
      this.gbOilC = engine.oilC >= 60 ? Math.max(ambient, Math.min(GEARBOX_WARM_C, engine.coolantC)) : ambient;
    }
    const rads = Math.PI / 30;
    const wE = Math.max(0, engine.rpm) * rads;
    const wIn = Math.max(0, inputRpm) * rads;
    const te = Number.isFinite(engine.torqueNm) ? engine.torqueNm : 0;
    const cap = Math.max(250, this.summary.peakTorqueNm * 1.6);
    let clutchSlipW = 0;
    let converterSlipW = 0;
    let coupled = false;
    if (converter && s.gear > 0) {
      coupled = true;
      const t = converterTorques(converter, engine.rpm, inputRpm);
      const lu = Math.min(1, Math.max(0, clutch));
      // the converter carries what the lock-up clutch does not; a slipping lock-up clutch is wet (in the ATF)
      converterSlipW = (1 - lu) * Math.max(0, t.pumpNm * wE - t.turbineNm * wIn) + Math.min(Math.abs(te), lu * cap) * Math.abs(wE - wIn);
    } else if (s.gear > 0 && clutch > 0) {
      coupled = true;
      clutchSlipW = Math.min(Math.abs(te), clutch * cap) * Math.abs(wE - wIn);
    }
    const pIn = coupled ? te * wE : 0;
    const powerW = Math.sign(pIn) * Math.max(0, Math.abs(pIn) - clutchSlipW - converterSlipW);
    this.gbOilC = stepGearboxOil(spec, this.gbOilC, dt, {
      powerW, efficiency: this.spec.efficiency, clutchSlipW, converterSlipW, shaftRpm: Math.max(inputRpm, outputRpm),
      airSpeedMs: vRoad, ambientC: ambient, coolantC: Number.isFinite(engine.coolantC) ? engine.coolantC : ambient, cooler: this.gbCooler,
      auxCoolerWK: this.gbAuxCoolerWK,
    });
    const T = this.gbOilC;
    this.gbWarn = this.gbWarn ? T >= spec.warnC - GEARBOX_HYST_K : T >= spec.warnC;
    // TCU protection mode (DSG, automatic, CVT, commercial): torque reduction like the real "Notlauf"; not in the sandbox
    const pc = spec.protectC;
    this.gbProtect = pc !== null && this.damageLevel !== "off" && (this.gbProtect ? T >= pc - GEARBOX_HYST_K : T >= pc);
    if (this.damageLevel !== "off") {
      this.gbWear = Math.min(this.damageLevel === "lenient" ? 0.99 : 1, this.gbWear + gearboxWearRate(spec, T) * dt);
      if (this.damageLevel === "real" && this.gbWear >= 1) this.gbFailed = true;
    }
    Object.assign(s, { gearboxOilC: T, gearboxOilWarn: this.gbWarn, gearboxProtect: this.gbProtect, gearboxWear: this.gbWear, gearboxFailed: this.gbFailed });
  }

  /** Shift timer, pending gear and launch-clutch memory back to rest (review #19). */
  private clearTransient() {
    this.cc.reset();
    this.shiftT = 0;
    this.pendingGear = 0;
    this.holdLaunch = 0;
    this.lockup = 0;
    this.holdSuppressed = false;
    this.lastBrake = 0;
    this.tc.reset();
    this.tcOut = { pedalCap: 1, torqueCut: 0, pedalFloor: 0 };
    this.resetGovernor();
  }

  private resetGovernor() {
    this.govActive = false;
    this.govI = 0;
    this.govCap = 1;
    this.govHold = null;
    this.st.limiting = false;
  }

  /**
   * Top-speed governor (issue #32): PI controller on the speed margin, output is a pedal cap. Takes over at
   * (limit − 5 km/h). The integrator only runs while the governor actually holds the pedal back; when the driver
   * lifts it is frozen (conditional-integration anti-windup), and its last hold value is remembered across a drop
   * out of the window, so full throttle after a lift picks up the hold point immediately (review PR #34).
   * First entry without a memory is bumpless (cap starts at the current pedal).
   */
  private governor(dt: number, speedKmh: number, pedal: number) {
    const s = this.st;
    const lim = s.speedLimitKmh;
    if (lim === null) {
      this.resetGovernor();
      return;
    }
    const e = lim - speedKmh; // remaining margin, km/h
    if (!this.govActive) {
      if (e > GOV_WINDOW_KMH) {
        this.govCap = 1;
        s.limiting = false;
        return;
      }
      this.govActive = true;
      this.govI = this.govHold ?? pedal - GOV_KP * e;
    } else if (e > GOV_WINDOW_KMH + 1) {
      // out of the window: release, but keep the integrator as hold memory
      this.govActive = false;
      this.govHold = this.govI;
      this.govCap = 1;
      s.limiting = false;
      return;
    }
    const outPrev = GOV_KP * e + this.govI;
    // integrate only while the governor is in control (its output below the driver pedal) or overspeed
    if (outPrev < pedal || e < 0) this.govI += GOV_KI * e * dt;
    this.govI = Math.min(1, Math.max(-0.5, this.govI));
    this.govHold = this.govI;
    this.govCap = Math.min(1, Math.max(0, GOV_KP * e + this.govI));
    s.limiting = this.govCap < pedal - 0.01;
    this.wheelieHold = 0;
  }

  /**
   * Cruise control and speed limiter (issue #30): set/off, resume, ±, limiter. The UI calls these; the controller
   * runs inside inputs() and its pedal is combined with the driver pedal in inputs() and effectivePedal().
   */
  get cruise(): CruiseControl {
    return this.cc;
  }

  /** Steady-state pedal estimate for the cruise control (issue #30): p · (F − m·a) / F with F the drive force. */
  private holdPedal(engine: EngineState, pedal: number, ratio: number): number | null {
    const f = (engine.torqueNm * ratio * this.st.finalDrive * this.spec.efficiency) / this.vehicle.wheelRadiusM;
    if (!(f > 200) || this.st.shifting || pedal < 0.05) return null;
    const share = (f - this.vehicle.massKg * (engine.accelMs2 ?? 0)) / f;
    return Number.isFinite(share) ? Math.min(1, Math.max(0, pedal * share)) : null;
  }

  /** Driver shift request: +1 up, −1 down. Ignored for CVT. */
  shift(dir: 1 | -1) {
    const s = this.st;
    if (s.type === "cvt" || this.evCfg) return;
    if (isAutomaticType(s.type)) s.manualMode = true;
    const target = Math.max(0, Math.min(s.gearCount, (s.shifting ? this.pendingGear : s.gear) + dir));
    // DSG refuses a downshift that would over-rev the engine (ECU protection); the manual gearbox lets you
    // do it – the limits model then reports the over-rev (review #19)
    if (isAutomaticType(s.type) && dir < 0 && target > 0 && this.rpmInGear(target, this.lastSpeedMs) > this.cfg.revLimitRpm * 0.97) return;
    this.beginShift(target);
  }

  /** DSG: back to D (automatic). */
  setAutomatic() {
    if (isAutomaticType(this.st.type)) this.st.manualMode = false;
  }

  private beginShift(target: number) {
    const s = this.st;
    if (target === s.gear && !s.shifting) return;
    this.pendingGear = target;
    this.shiftDir = target < s.gear ? -1 : 1;
    this.shiftT = s.type === "sequential" && this.shiftDir < 0 ? SEQ_DOWNSHIFT_S : this.spec.shiftTimeS;
    s.shifting = true;
  }

  /**
   * Hard launch (issue #22): with the pedal beyond half the driver keeps the clutch slipping until the input shaft
   * reaches ≈ 60 % of the launch speed, so a turbo engine is not pulled down into its boost lag [S].
   */
  private launchSyncRpm(pedal: number): number {
    if (pedal < 0.5) return 0;
    return 0.6 * this.launchRpm(pedal);
  }

  /**
   * Launch speed of the automatic clutch: rises with the pedal; full pedal ≈ 45 % of the limiter (test-driver
   * launch, petrol sports cars 3000–4000 rpm so a turbo has boost; the clutch is dosed by traction, so no burnout). Converter automatic: stall speed ≈ lock-up
   * speed + 600 rpm [S] (issue #22, review PR #37).
   */
  private launchRpm(pedal: number): number {
    const idle = this.cfg.idleRpm;
    const lock = this.spec.converterLockRpm;
    return lock ? idle + pedal * Math.max(300, lock + 600 - idle) : idle + 200 + pedal * Math.max(900, 0.45 * this.cfg.revLimitRpm - idle - 200);
  }

  /** Engine rpm the gear `g` would give at the current speed. */
  private rpmInGear(g: number, speedMs: number): number {
    const ratio = this.spec.ratios[g - 1] ?? 1;
    return (speedMs / this.vehicle.wheelRadiusM) * ratio * this.st.finalDrive * RAD_TO_RPM;
  }

  /**
   * Called once per frame BEFORE simulator.step(): updates shift logic, clutch and CVT ratio from the last engine
   * state and returns the coupling for this frame.
   */
  inputs(dt: number, engine: EngineState, driverPedal: number, brake = 0): VehicleCoupling {
    if (this.evCfg) return this.evInputs(dt, engine, driverPedal, brake, this.evCfg);
    const s = this.st;
    // cruise control / limiter (issue #30): from here on "pedal" is the commanded pedal (shift schedule, CVT target,
    // launch, ASR and the governor all see what the engine is asked for)
    const pedal = this.cc.command(driverPedal);
    const g = this.spec;
    // the gearbox sees the driven wheels; they run ahead of the road speed while spinning (issue #22)
    const vRoad = engine.vehicleSpeedMs ?? 0;
    const v = engine.wheelSpeedMs ?? vRoad;
    this.lastSpeedMs = v;
    // route position from the road speed (#48): the gradient and altitude follow the profile
    if (Number.isFinite(vRoad) && dt > 0 && dt < 1) {
      this.positionM += vRoad * dt;
      this.updateRoad(dt);
    }
    this.updateHold(Number.isFinite(vRoad) ? vRoad : 0, pedal, brake, engine);
    const held = !!s.parkingBrake;
    const rpm = engine.rpm;
    this.lastRpm = rpm;
    const idle = this.cfg.idleRpm;
    const limit = this.cfg.revLimitRpm;

    // --- shift execution
    this.gearDwell = Math.max(0, this.gearDwell - dt);
    this.ccDownT = Math.max(0, this.ccDownT - dt);
    if (s.shifting) {
      this.shiftT -= dt;
      if (this.shiftT <= 0) {
        s.gear = this.pendingGear;
        s.shifting = false;
        // DSG schedule: at least 0.5 s in a gear before the next automatic upshift, so a short rpm flare (wheel slip,
        // clutch handover) does not skip a gear (review PR #37) [S]
        this.gearDwell = 0.5;
      }
    }

    // torque request the engine really gets (governor cap from the last frame): DSG shift points and CVT target
    // follow it, so with the governor holding the speed they settle at low rpm instead of fighting it (issue #32)
    const req = this.govActive ? Math.min(pedal, this.govCap) : pedal;

    // --- DSG automatic shift schedule (Drive mode) [S]: upshift point rises with pedal, downshift keeps torque
    // converter automatic (issue #14): the schedule works on the turbine speed (output speed × gear, like a TCU), the
    // engine runs ahead of it while the converter slips (upshift also on the engine speed, so a slipping converter
    // does not hold the engine in the limiter)
    const conv = s.type === "automatic";
    const schedRpm = conv ? this.rpmInGear(s.gear, v) : rpm;
    if (isAutomaticType(s.type) && !s.shifting && s.gear > 0) {
      // low-revving truck engines (limit < 3000 rpm, issue #31): top of the schedule 150 rpm below the limit, i.e.
      // ahead of the diesel governor ramp (starts ≈ 200 rpm under the limit, diesel.md §3.2d), so they still upshift
      // at full load; all other engines keep 0.97 × limit unchanged
      const upTop = limit < 3000 ? Math.min(limit * 0.97, limit - 150) : limit * 0.97;
      const upRpm = Math.min(upTop, idle + 900 + Math.pow(req, 0.8) * (upTop - idle - 900));
      const downRpm = Math.max(idle * 1.35, upRpm * 0.42);
      if (!s.manualMode) {
        // engine-brake downshift (issue #31, AMT "Bremsschaltung"): rolling downhill on overrun with the engine brake
        // working, the AMT holds a lower gear so the engine brake runs near rated speed (braking power ∝ n²)
        const ebDown = !!this.cfg.engineBrake && pedal < 0.01 && (engine.accelMs2 ?? 0) > 0.05 && engine.engineBrakeActive === true
          && s.gear > 1 && rpm < 0.8 * limit && this.rpmInGear(s.gear - 1, v) < 0.95 * limit;
        // …and does not shift up again while the engine brake works below the limiter (no hunting)
        const ebHold = !!this.cfg.engineBrake && pedal < 0.01 && engine.engineBrakeActive === true && rpm < 0.95 * limit;
        if (ebDown) {
          if (this.gearDwell <= 0) this.beginShift(s.gear - 1);
        } else if (!ebHold && this.gearDwell <= 0 && Math.max(schedRpm, rpm) > upRpm && s.gear < s.gearCount && this.rpmInGear(s.gear + 1, v) > idle * 1.25) this.beginShift(s.gear + 1);
        else if (schedRpm < downRpm && s.gear > 1 && this.rpmInGear(s.gear - 1, v) < limit * 0.9) this.beginShift(s.gear - 1);
        // cruise control (issue #30): speed not holdable at full pedal → one gear down if the engine then runs closer
        // to its power peak (like a kickdown), at most every 3 s so it cannot hunt
        else if (this.cc.state.notHoldable && this.ccDownT <= 0 && s.gear > 1 && rpm < this.summary.peakPowerRpm
          && this.rpmInGear(s.gear - 1, v) < Math.min(limit * 0.9, this.summary.peakPowerRpm * 1.15)) {
          this.beginShift(s.gear - 1);
          this.ccDownT = 3;
        }
      } else if (schedRpm < idle * 1.1 && s.gear > 1) {
        // M mode still protects against stalling
        this.beginShift(s.gear - 1);
      }
    }

    // --- ratio
    let ratio: number;
    if (s.type === "cvt") {
      // CVT holds a target engine speed set by the pedal (between idle and peak power) [S]
      const nPeak = this.summary.peakPowerRpm;
      // target from the governed pedal, so the CVT does not hold high rpm against the governor (issue #32)
      const target = idle + 300 + Math.pow(req, 1.3) * (nPeak - idle - 300);
      const wheel = (v / this.vehicle.wheelRadiusM) * s.finalDrive * RAD_TO_RPM;
      const [lo, hi] = [g.ratios[1]!, g.ratios[0]!];
      const want = wheel > 1 ? Math.min(hi, Math.max(lo, target / wheel)) : hi;
      // ratio change rate limited (chain/belt) ≈ 1.5 /s
      const maxStep = 1.5 * dt;
      ratio = s.ratio + Math.max(-maxStep, Math.min(maxStep, want - s.ratio));
    } else {
      // DSG with ASR (issue #23): during the shift the on-coming clutch already carries the new gear (inertia phase,
      // the engine is pulled down to the new synchronous speed instead of being dumped onto the wheels at the end)
      const gNow = s.type === "dsg" && s.shifting && this.assistSet.asr && this.pendingGear > 0 ? this.pendingGear : s.gear;
      ratio = gNow > 0 ? g.ratios[gNow - 1]! : 0;
    }
    s.ratio = ratio;

    // --- clutch: automatic launch control and shift interruption
    const inputRpm = s.gear > 0 ? (v / this.vehicle.wheelRadiusM) * ratio * s.finalDrive * RAD_TO_RPM : 0;
    let clutch: number;
    let torqueRatio = 1;
    let launchHoldRpm = 0;
    let launchLimitRpm = 0;
    s.launchArmed = false;
    let tractionLimited = false;
    // Engine not running (ignition off, stalled). Manual and sequential: a gear is engaged and the clutch pedal is
    // released, so the rolling car drags the engine along (friction and pumping work brake the car, like rolling
    // downhill in gear with the ignition off; parked in gear on a slope the engine's compression holds the car).
    // DSG, converter, CVT: without a running engine there is no oil pressure, the
    // clutches open (review #19). A destroyed engine is declutched by the driver.
    const dragged = !engine.running && !engine.destroyed && s.gear > 0 && (s.type === "manual" || s.type === "sequential")
      && !s.shifting && !engine.starterEngaged; // cranking: the driver holds the clutch pedal down
    if (dragged) {
      this.holdLaunch = 0;
      // held at rest (issue #91): the driver lets the clutch in only once the engine has run down, so its inertia does
      // not jerk the locked car
      clutch = held && vRoad < 0.1 && rpm > 50 ? 0 : 1;
    } else if (s.gear === 0 || !engine.running) {
      clutch = 0;
      this.lockup = 0;
    } else if (conv) {
      // converter automatic (issue #14): the converter always couples (creep in D, also against the brake); the
      // lock-up clutch closes above the lock-up turbine speed (later with more pedal, from 2nd gear at full load)
      // and opens when the turbine speed falls back or the car brakes to a stop (vehicle.md §4) [S]
      const lu = g.converter?.lockUpRpm ?? 1300;
      const on = lu * (1 + 0.5 * pedal);
      const want = (s.gear >= 2 || pedal < 0.5) && inputRpm > (this.lockup > 0 ? 0.85 * on : on) && !((brake > 0.05 || held) && pedal < 0.02 && inputRpm < idle * 1.4);
      this.lockup = want ? Math.min(1, this.lockup + 2 * dt) : Math.max(0, this.lockup - 10 * dt);
      // during a shift a closed lock-up clutch slips (controlled slip), the converter takes the speed step
      clutch = s.shifting ? Math.min(this.lockup, 0.6) : this.lockup;
    } else if (s.shifting) {
      // manual: open; DSG: second clutch takes over, slip syncs within the shift; sequential: dog rings
      // disengaged (no torque) while the quickshifter cuts the ignition
      clutch = s.type === "dsg" ? 0.85 : 0;
    } else if (this.assistSet.launchControl && brake > 0.05 && pedal > 0.5 && vRoad < 0.5 && s.type !== "sequential") {
      // launch control (issue #23): at standstill with brake and throttle the clutch stays open; releasing the brake
      // starts the traction-dosed launch of the next branch [S]. Issue #38: the throttle stays wide open and the
      // engine's secondary rev limiter holds the launch speed (VehicleCoupling.launchLimitRpm, docs/research/vehicle.md §9)
      this.holdLaunch = 0;
      clutch = 0;
      launchLimitRpm = this.launchRpm(pedal);
      s.launchArmed = true;
    } else if ((brake > 0.05 || held) && pedal < 0.02 && inputRpm < idle * 1.4) {
      // braking down to a stop (or held by the parking brake, issue #91): the automatic clutch opens before the engine is dragged below idle.
      // With pedal AND brake (left-foot braking) the clutch stays engaged on purpose: the engine works against
      // the brake and can stall, like a real car (review #20).
      this.holdLaunch = 0;
      clutch = 0;
    } else if (inputRpm < (s.type === "sequential" ? Math.max(idle * 1.05, 0.4 * limit)
      : Math.max(idle * 1.05, g.converterLockRpm ?? 0, this.holdLaunch < 1 ? this.launchSyncRpm(pedal) : 0))) {
      // launch: engage with engine speed above idle (anti-stall), harder with pedal
      let want: number;
      if (s.type === "sequential") {
        // motorcycle (#25): the rider holds the engine near 60 % of the limiter and slips the clutch until the
        // input shaft reaches ≈ 40 % of the limiter (superbike launch technique) [S]
        const launchRpm = idle + pedal * (0.6 * limit - idle);
        want = pedal > 0.02 ? Math.min(1, Math.max(0, (rpm - 0.85 * launchRpm) / Math.max(1, 0.15 * launchRpm))) : 0;
      } else {
        const launchRpm = this.launchRpm(pedal);
        launchHoldRpm = launchRpm;
        // quadratic engagement: the clutch bites gently near idle, so the engine (and the turbo) can rise towards
        // the launch speed before the clutch carries the full torque (issue #22, launch with traction limit)
        // full pedal (hard launch): the clutch only starts to bite from 70 % of the launch speed, so a turbo engine
        // gets onto its boost before it takes load (review PR #37)
        const lo = pedal > 0.9 ? Math.max(idle * 0.9, 0.7 * launchRpm) : idle * 0.9;
        const x = Math.min(1, Math.max(0, (rpm - lo) / Math.max(1, launchRpm - lo)));
        want = pedal > 0.02 ? x * x : 0;
      }
      this.holdLaunch += (want - this.holdLaunch) * Math.min(1, dt * 15);
      clutch = this.holdLaunch * 0.9;
      // torque converter (issue #22): torque ratio ≈ 2.0 at stall falling linearly to 1 at speed ratio 0.85
      // (coupling point), typical passenger-car converter characteristic (Naunheimer et al., Automotive
      // Transmissions, ch. 9 "Hydrodynamic torque converter") [S]
      if (g.converterLockRpm && rpm > 1) torqueRatio = 1 + Math.max(0, 1 - inputRpm / rpm / 0.85);
    } else {
      this.holdLaunch = 1;
      // manual: driver lets the clutch in within ≈ 0.15 s after a shift (review PR #37); sequential: dog engagement,
      // only the slipper clutch smooths it (≈ 30 ms) [S]
      clutch = Math.min(1, s.clutch + dt * (s.type === "manual" ? 7 : s.type === "sequential" ? 30 : 10));
      // closing right after the launch (below ≈ 30 km/h): still dosed by traction (review PR #37), engine held just
      // above the input shaft so it does not flare while the clutch slips
      if (s.type !== "sequential" && clutch < 0.98 && s.gear > 0 && rpm - inputRpm > 150 && (vRoad < 8 || (this.assistSet.asr && (s.type === "dsg" || this.tcCutting)))) launchHoldRpm = Math.max(this.launchRpm(pedal), inputRpm + 500);
    }
    if (launchHoldRpm > 0 && s.type !== "sequential" && s.gear > 0 && this.vehicle.driveLayout) {
      // traction-limited launch (review PR #37): the automatic clutch lets in only the torque the driven tyres can
      // carry at their μ peak (μ·N with load transfer); the driver/ECU then holds the launch speed with the pedal
      // instead of flaring the engine. With a standard tyre and 400+ kW the wheels still spin after the clutch
      // has closed – only the launch itself is dosed.
      const total = ratio * s.finalDrive;
      const n = drivenAxleLoadN(this.vehicle, Math.max(0, engine.accelMs2 ?? 0));
      const capNm = Math.max(250, this.summary.peakTorqueNm * 1.6);
      if (Number.isFinite(n) && total > 0) {
        // with ASR (issue #23) the clutch is dosed just below the peak (× 0.97) and follows the ASR torque cap, so a
        // slipping launch clutch cannot overpower the tyre while the engine torque is being cut
        const asrK = this.assistSet.asr ? (s.grip < 0.9 || vRoad < 1.5 ? 0.97 : 1) * (this.tcOut.torqueCut > 0 || this.tcCutting ? Math.min(1, 0.3 + this.tcOut.pedalCap) : 1) : 1;
        const tcMax = (asrK * s.grip * n * this.vehicle.wheelRadiusM) / (total * g.efficiency * torqueRatio);
        if (tcMax / capNm < clutch) tractionLimited = true;
        clutch = Math.min(clutch, tcMax / capNm);
      }
    }
    if (s.type === "dsg" && s.shifting && this.assistSet.asr && this.vehicle.driveLayout && ratio > 0) {
      // the on-coming clutch is dosed by traction too (issue #23), the engine syncs through the slipping clutch
      const n = drivenAxleLoadN(this.vehicle, Math.max(0, engine.accelMs2 ?? 0));
      const capNm = Math.max(250, this.summary.peakTorqueNm * 1.6);
      if (Number.isFinite(n)) clutch = Math.min(clutch, (0.97 * s.grip * n * this.vehicle.wheelRadiusM) / (ratio * s.finalDrive * g.efficiency) / capNm);
    }
    // gearbox failed (issue #53, realism "real"): no drive until reset
    if (this.gbFailed) clutch = 0;
    s.clutch = clutch;
    // launch speed hold: above the launch speed the pedal is taken back (clutch dosed by traction)
    this.launchCap = launchHoldRpm > 0 && rpm > launchHoldRpm ? Math.max(0.2, 1 - (rpm - launchHoldRpm) / 800) : 1;

    // --- wheelie indicator: drive force the engine would deliver vs. the limit (shown ≥ 0.3 s) (#25)
    const fLimit = wheelieLimitN(this.vehicle);
    const fEngine = (Math.max(0, engine.torqueNm) * ratio * s.finalDrive * g.efficiency) / this.vehicle.wheelRadiusM;
    if (Number.isFinite(fLimit) && s.gear > 0 && clutch > 0.3 && fEngine * Math.min(1, clutch / 0.9) > fLimit) this.wheelieHold = 0.3;
    else this.wheelieHold = Math.max(0, this.wheelieHold - dt);
    s.wheelie = this.wheelieHold > 0;

    // --- tyres (issue #22): tread temperature, μ, wheel-spin indicator
    this.roadKmh = vRoad * 3.6;
    const mu = this.currentGrip();
    // rolling part of the tread temperature; the slip part is the friction-power model of issue #149 (stepTyres)
    this.tyreT = stepTyreTemp(this.tyreT, dt, (engine.tyreForceN ?? 0) / Math.max(1, mu * this.vehicle.massKg * 9.81), vRoad, 0, this.env.ambientC);
    this.stepTyres(dt, vRoad, this.slipFrictionW(engine, v, vRoad, brake, mu), !!(engine.wheelSpin || engine.wheelsLocked), !!engine.wheelsLocked);
    s.tyreTempC = this.treadC();
    s.grip = this.currentGrip();
    this.spinHold = engine.wheelSpin ? 0.3 : Math.max(0, this.spinHold - dt);
    s.wheelSpin = this.spinHold > 0;
    s.wheelsLocked = engine.wheelsLocked ?? false;
    s.aquaplaning = this.aquaplane && aquaplaningFactor(this.tyreSetup.type, this.roadKmh, this.tyreSetup.size.widthMm) < 0.9;

    // --- driver assistance (issue #23): ASR/MSR on the driven-wheel slip of the last step, lamps
    const a = this.assistSet;
    const tcr = this.tc.step(dt, engine.wheelSlip ?? 0, vRoad, pedal, this.cfg.fuel === "petrol", a, brake > 0.05, this.lastEffPedal, s.grip);
    this.tcOut = { pedalCap: tcr.pedalCap, torqueCut: tcr.torqueCut, pedalFloor: tcr.pedalFloor };
    this.tcCutting = tcr.cutting;
    this.absHold = a.abs && engine.absActive ? ASSIST_LAMP_HOLD_S : Math.max(0, this.absHold - dt);
    // the ESP lamp also flashes while ASR doses the launch clutch on a slippery road (μ < 0.9)
    this.asrHold = tcr.asrActive || (a.asr && tractionLimited && s.grip < 0.9 && vRoad > 0.5) ? ASSIST_LAMP_HOLD_S : Math.max(0, this.asrHold - dt);
    // the ESP lamp flashes for ASR and MSR interventions (as in the cluster); ABS has its own lamp
    this.espHold = tcr.msrActive || (a.esp && tcr.asrActive) ? ASSIST_LAMP_HOLD_S : Math.max(0, this.espHold - dt);
    s.absActive = this.absHold > 0;
    s.asrActive = this.asrHold > 0;
    s.espActive = this.espHold > 0;
    // shift torque intervention of the DSG with ASR (ignition retard in the inertia phase, ≈ 40 %) [S: Naunheimer et
    // al., Automotive Transmissions, "Schaltablauf Doppelkupplungsgetriebe": engine torque reduction during the shift]
    const cut = Math.max(tcr.torqueCut, s.type === "dsg" && s.shifting && a.asr ? 0.4 : 0);

    // --- measurements
    s.speedKmh = vRoad * 3.6;
    this.governor(dt, s.speedKmh, pedal);
    this.cc.update(dt, {
      speedKmh: s.speedKmh, driverPedal, brake, running: engine.running, gear: s.gear,
      clutchOpen: s.type === "manual" && s.shifting, manual: s.type === "manual", rpm, idleRpm: idle,
      governorKmh: s.speedLimitKmh, holdPedal: this.holdPedal(engine, pedal, ratio),
    });
    if (s.speedKmh > s.maxSpeedKmh) {
      s.maxSpeedKmh = s.speedKmh;
      s.maxSpeedLimited = this.govActive && s.speedLimitKmh !== null && s.speedKmh >= s.speedLimitKmh - 3;
    }
    this.track0to100(dt, pedal, brake, engine.running);

    const converter = conv && s.gear > 0 && engine.running && !this.gbFailed ? this.converterCoupling() : undefined;
    // gearbox oil (issue #53): the output shaft turns with the wheels also in N
    const outputRpm = (v / this.vehicle.wheelRadiusM) * s.finalDrive * RAD_TO_RPM;
    this.stepGearboxOil(dt, engine, clutch, inputRpm, outputRpm, converter, Number.isFinite(vRoad) ? vRoad : 0);
    const torqueLimitNm = converter && brake > BTM_BRAKE_ON && pedal > 0.02 && Math.abs(Number.isFinite(vRoad) ? vRoad : 0) < 0.1 ? this.brakeStandLimit(ratio * s.finalDrive, g.efficiency, brake) : 0;
    return {
      vehicle: this.couplingVehicle(vRoad),
      totalRatio: ratio * s.finalDrive,
      // cold, viscous oil costs efficiency (issue #53, vehicle.md §8); not on the shared motorcycle sump
      efficiency: g.efficiency - (s.type === "sequential" ? 0 : gearboxDragPenalty(this.gbOilC)),
      clutch,
      clutchCapacityNm: Math.max(250, this.summary.peakTorqueNm * 1.6),
      brake,
      grip: s.grip,
      ...(torqueRatio > 1 ? { torqueRatio } : {}),
      abs: a.abs,
      gradePct: this.road.gradePct,
      airDensityKgM3: airDensity(altitudeToKpa(this.airAltM), this.env.ambientC),
      ...(cut > 0 ? { torqueCut: cut } : {}),
      ...(s.shifting ? { shifting: true } : {}),
      ...(converter ? { converter } : {}),
      ...(held ? { parkingBrake: true } : {}),
      ...(launchLimitRpm > 0 ? { launchLimitRpm } : {}),
      ...(torqueLimitNm > 0 ? { torqueLimitNm } : {}),
    };
  }

  /**
   * 0–100 km/h timer: armed at standstill, it starts when the car is let go under throttle (gas on, brake off;
   * revving against the brake or launch control does not count yet). An automatic that creeps off the brake first
   * still counts if the gas goes on below 5 km/h. Lifting off for longer than a short pause (not while shifting),
   * braking, or the engine stopping discards the run.
   */
  private t100Armed = false;
  private t100LiftS = 0;
  private track0to100(dt: number, pedal: number, brake: number, running: boolean) {
    const s = this.st;
    if (!running) {
      s.t0to100Running = null;
      this.t100Armed = false;
      return;
    }
    if (s.speedKmh < 0.5 && (pedal <= 0.05 || brake > 0.05)) {
      s.t0to100Running = null;
      this.t100Armed = true;
      this.t100LiftS = 0;
      return;
    }
    if (s.t0to100Running === null) {
      if (!this.t100Armed || s.speedKmh >= 5) {
        this.t100Armed = false; // already rolling: only a (near) standing start counts
        return;
      }
      if (pedal <= 0.05 || brake > 0.05) return; // creeping off the brake: still armed
      s.t0to100Running = 0;
      this.t100Armed = false;
      this.t100LiftS = 0;
    }
    if (pedal >= 0.05) this.t100LiftS = 0;
    else if (!s.shifting) this.t100LiftS += dt; // a shift pause does not count as lifting off
    if (brake > 0.05 || this.t100LiftS > 0.6) {
      s.t0to100Running = null; // off the throttle: this run does not count
      return;
    }
    s.t0to100Running += dt;
    if (s.speedKmh >= 100) {
      s.t0to100S = s.t0to100Running;
      s.t0to100Running = null;
    }
  }

  /**
   * Brake-torque protection of the converter automatic (issues #104, #119): standing in D with brake and throttle,
   * engine and gearbox management cap the engine torque so the stall torque at the wheels, T·μ₀·i·η, stays at 90 % of
   * what the braked driven wheels hold (own brake + μ·N, vehicle.ts). Protects converter and driveline; OEMs manage
   * combined brake + throttle at standstill (e.g. GM US 11,390,281 B2, not verified). Calibration is an estimate [S]. Faded in over the brake pedal
   * BTM_BRAKE_ON … BTM_BRAKE_FULL (no torque step at the threshold). 0 = no cap
   * needed (the brakes hold full stall, e.g. AWD).
   */
  private brakeStandLimit(totalRatio: number, efficiency: number, brake: number): number {
    const mu0 = Math.max(1, this.spec.converter?.stallTorqueRatio ?? 1);
    if (!(totalRatio > 0)) return 0;
    const limit = (0.9 * brakeStandHoldN(this.vehicle, brake, this.st.grip) * this.vehicle.wheelRadiusM) / (mu0 * totalRatio * efficiency);
    const peak = this.summary.peakTorqueNm;
    if (!(limit < peak)) return 0;
    const w = Math.min(1, Math.max(0, (brake - BTM_BRAKE_ON) / (BTM_BRAKE_FULL - BTM_BRAKE_ON)));
    return peak + (Math.max(0, limit) - peak) * w;
  }

  /**
   * Electric car (issue #108): the motors sit on the wheels through a single-speed reduction, so there is no shift
   * schedule, clutch, launch or anti-stall logic. Route, Auto-Hold, tyres, assistants, governor, cruise control and
   * the measurements are the same as in inputs(). The reduction-gear oil runs in the drive unit's cooling circuit:
   * its temperature is the motor temperature, no gearbox protection mode.
   */
  private evInputs(dt: number, engine: EngineState, driverPedal: number, brake: number, ev: EvConfig): VehicleCoupling {
    const s = this.st;
    const pedal = this.cc.command(driverPedal);
    const vRoad = engine.vehicleSpeedMs ?? 0;
    const v = engine.wheelSpeedMs ?? vRoad;
    this.lastSpeedMs = v;
    if (Number.isFinite(vRoad) && dt > 0 && dt < 1) {
      this.positionM += vRoad * dt;
      this.updateRoad(dt);
    }
    // the "clutch" of an EV is always closed; for the Auto-Hold release it counts as open (drive-away by pedal only)
    // two-speed reduction (Taycan-like): the EvSimulator shifts, the drivetrain shows its gear
    Object.assign(s, { gear: engine.ev?.gear ?? 1, gearCount: ev.twoSpeed ? 2 : 1, ratio: 1, shifting: !!engine.ev?.shifting, clutch: 0, manualMode: false, launchArmed: false, wheelie: false, electric: true });
    this.updateHold(Number.isFinite(vRoad) ? vRoad : 0, pedal, brake, engine);
    const held = !!s.parkingBrake;
    this.lastRpm = engine.rpm;
    this.launchCap = 1;
    // --- tyres (issue #22)
    this.roadKmh = vRoad * 3.6;
    const mu = this.currentGrip();
    // rolling part of the tread temperature; the slip part is the friction-power model of issue #149 (stepTyres)
    this.tyreT = stepTyreTemp(this.tyreT, dt, (engine.tyreForceN ?? 0) / Math.max(1, mu * this.vehicle.massKg * 9.81), vRoad, 0, this.env.ambientC);
    this.stepTyres(dt, vRoad, this.slipFrictionW(engine, v, vRoad, brake, mu), !!(engine.wheelSpin || engine.wheelsLocked), !!engine.wheelsLocked);
    s.tyreTempC = this.treadC();
    s.grip = this.currentGrip();
    this.spinHold = engine.wheelSpin ? 0.3 : Math.max(0, this.spinHold - dt);
    s.wheelSpin = this.spinHold > 0;
    s.wheelsLocked = engine.wheelsLocked ?? false;
    s.aquaplaning = this.aquaplane && aquaplaningFactor(this.tyreSetup.type, this.roadKmh, this.tyreSetup.size.widthMm) < 0.9;
    // --- assistants (issue #23): the motor torque reacts like the ignition path of a petrol engine (fast cut)
    const a = this.assistSet;
    const tcr = this.tc.step(dt, engine.wheelSlip ?? 0, vRoad, pedal, true, a, brake > 0.05, this.lastEffPedal, s.grip);
    this.tcOut = { pedalCap: tcr.pedalCap, torqueCut: tcr.torqueCut, pedalFloor: tcr.pedalFloor };
    this.tcCutting = tcr.cutting;
    this.absHold = a.abs && engine.absActive ? ASSIST_LAMP_HOLD_S : Math.max(0, this.absHold - dt);
    this.asrHold = tcr.asrActive || (a.asr && engine.ev?.limitedBy === "traction" && s.grip < 0.9 && vRoad > 0.5) ? ASSIST_LAMP_HOLD_S : Math.max(0, this.asrHold - dt);
    this.espHold = tcr.msrActive || (a.esp && tcr.asrActive) ? ASSIST_LAMP_HOLD_S : Math.max(0, this.espHold - dt);
    s.absActive = this.absHold > 0;
    s.asrActive = this.asrHold > 0;
    s.espActive = this.espHold > 0;
    // --- measurements (same as inputs())
    s.speedKmh = vRoad * 3.6;
    this.governor(dt, s.speedKmh, pedal);
    this.cc.update(dt, {
      speedKmh: s.speedKmh, driverPedal, brake, running: engine.running, gear: 1, clutchOpen: false, manual: false,
      rpm: engine.rpm, idleRpm: 0, governorKmh: s.speedLimitKmh, holdPedal: this.holdPedal(engine, pedal, 1),
    });
    if (s.speedKmh > s.maxSpeedKmh) {
      s.maxSpeedKmh = s.speedKmh;
      s.maxSpeedLimited = this.govActive && s.speedLimitKmh !== null && s.speedKmh >= s.speedLimitKmh - 3;
    }
    this.track0to100(dt, pedal, brake, engine.running);
    const motorC = engine.ev?.motorC ?? this.env.ambientC;
    this.gbOilC = motorC;
    Object.assign(s, { gearboxOilC: motorC, gearboxOilWarn: false, gearboxProtect: false, gearboxWear: 0, gearboxFailed: false });
    const cut = tcr.torqueCut;
    return {
      vehicle: this.couplingVehicle(vRoad),
      totalRatio: evRefRatio(ev),
      efficiency: ev.gearEfficiency,
      clutch: 1,
      clutchCapacityNm: 1e7,
      brake,
      grip: s.grip,
      abs: a.abs,
      asr: a.asr,
      gradePct: this.road.gradePct,
      airDensityKgM3: airDensity(altitudeToKpa(this.airAltM), this.env.ambientC),
      ...(cut > 0 ? { torqueCut: cut } : {}),
      ...(held ? { parkingBrake: true } : {}),
    };
  }

  /**
   * Converter characteristic for the simulator (issue #14): K from the stall speed and the engine's peak torque – the
   * converter is matched to the engine, so a stronger engine gets a stiffer converter (vehicle.md §4) [S].
   */
  private converterCoupling(): ConverterCoupling | undefined {
    const c = this.spec.converter;
    if (!c) return undefined;
    return { kFactor: converterK(c.stallRpm, this.torqueAtStall(c.stallRpm)), stallTorqueRatio: c.stallTorqueRatio, couplingPoint: c.couplingPoint };
  }

  /** Steady full-load torque at the stall speed (dyno.ts), cached per engine; the peak torque as fallback. */
  private torqueAtStall(rpm: number): number {
    let t = this.stallTorque.get(rpm);
    if (t === undefined) {
      try {
        t = dynoSweep(this.cfg, { fromRpm: rpm, toRpm: rpm, stepRpm: 10 })[0]?.torqueNm ?? Number.NaN;
      } catch {
        t = Number.NaN;
      }
      if (!(t > 10)) t = this.summary.peakTorqueNm;
      this.stallTorque.set(rpm, t);
    }
    return t;
  }

  /**
   * Pedal actually sent to the engine: a manual shift lifts off (driver lifts, clutch open) so the engine does not
   * flare to the limiter; DSG/CVT pass the pedal through (the ECU blips/cuts torque internally).
   * The top-speed governor (issue #32) caps the pedal; the cap is updated in inputs().
   */
  effectivePedal(driverPedal: number): number {
    const pedal = this.cc.command(driverPedal);
    if (this.st.type === "sequential" && this.st.shifting) {
      // quickshifter: ignition cut on the upshift (rider keeps the throttle open); blipper opens on the downshift
      return this.shiftDir > 0 ? 0 : Math.max(Math.min(pedal, this.govActive ? this.govCap : 1), 0.35);
    }
    if (this.st.type === "manual" && this.st.shifting) {
      // downshift with double-declutch blip ("Zwischengas", issue #14): the driver blips the throttle while the
      // clutch is open until the engine reaches the new gear's speed, so the clutch closes without a jolt [S]
      if (this.shiftDir > 0 || this.pendingGear <= 0) return 0;
      const target = this.rpmInGear(this.pendingGear, this.lastSpeedMs);
      return this.lastRpm < target - 100 ? Math.min(0.6, 0.15 + (target - this.lastRpm) / 3000) : 0;
    }
    // ASR pedal cap and MSR pedal floor (issue #23); TCU protection mode at gearbox overtemperature (issue #53)
    const p = Math.max(Math.min(pedal, this.launchCap, this.tcOut.pedalCap, this.gbProtect ? GEARBOX_PROTECT_PEDAL : 1), this.tcOut.pedalFloor);
    this.lastEffPedal = this.govActive ? Math.min(p, this.govCap) : p;
    return this.lastEffPedal;
  }

  /** Label for the gear indicator: "N", "3", "D4", "M4", "CVT". */
  gearLabel(): string {
    const s = this.st;
    if (this.evCfg) return "D";
    if (s.type === "cvt") return s.gear === 0 ? "N" : "D";
    if (s.gear === 0) return "N";
    if (isAutomaticType(s.type)) return `${s.manualMode ? "M" : "D"}${s.gear}`;
    return String(s.gear);
  }
}

/**
 * Theoretical top speed: highest speed where drive force (any gear, rpm ≤ limiter) ≥ road load.
 * Also reports whether the limiter or the road load decides ("zu kurz" vs. "Leistung reicht nicht").
 */
export function theoreticalVmax(
  torqueAt: (rpm: number) => number, limitRpm: number, type: GearboxType, finalDrive: number,
  vehicle: VehicleParams = DEFAULT_VEHICLE, spec: GearboxSpec = GEARBOXES[type],
): { vmaxKmh: number; limitedBy: "limiter" | "power"; gear: number } {
  const g = spec;
  const ratios = type === "cvt" ? Array.from({ length: 40 }, (_, k) => g.ratios[0]! + ((g.ratios[1]! - g.ratios[0]!) * k) / 39) : g.ratios;
  let best = { vmaxKmh: 0, limitedBy: "power" as "limiter" | "power", gear: 1 };
  ratios.forEach((ratio, idx) => {
    const i = ratio * finalDrive;
    for (let v = 1; v < 130; v += 0.25) {
      const rpm = (v / vehicle.wheelRadiusM) * i * RAD_TO_RPM;
      if (rpm > limitRpm) {
        if (v * 3.6 > best.vmaxKmh) best = { vmaxKmh: (v - 0.25) * 3.6, limitedBy: "limiter", gear: idx + 1 };
        break;
      }
      const fDrive = (torqueAt(Math.max(rpm, 800)) * i * g.efficiency) / vehicle.wheelRadiusM;
      const fRes = vehicle.rollingResistance * vehicle.massKg * 9.81 + 0.5 * 1.2 * vehicle.dragCoefficient * vehicle.frontalAreaM2 * v * v;
      if (fDrive < fRes) {
        if (v * 3.6 > best.vmaxKmh) best = { vmaxKmh: v * 3.6, limitedBy: "power", gear: idx + 1 };
        break;
      }
    }
  });
  return best;
}
