// Switchable fields of the digital cockpit design (#83): which values a field can show, how they read in the chosen
// units and the cycling order. Pure (no DOM), so the formatting is unit-tested.
import type { EngineLimits } from "../../core/index.ts";
import { fmt } from "../format.ts";
import type { UnitPrefs } from "../settings.ts";
import { CONV, toUnit } from "../units.ts";
import { FIELD_IDS, type FieldId } from "./designs.ts";

/** Everything a field may show, in base units (°C, bar, l/h, km/h, l, kW, Nm, m). NaN or null = not known. */
export interface FieldInputs {
  coolantC: number;
  oilC: number;
  oilPressureBar: number;
  boostBar: number;
  egtC: number;
  fuelFlowLh: number;
  speedKmh: number;
  running: boolean;
  /** Tank content (chassis dyno), NaN on the engine dyno. */
  tankLevelL: number;
  /** Average consumption of trip A, l/100 km (NaN while too short). */
  avgL100: number;
  /** Live range from the rolling consumption (range-estimator.ts), km; preferred over tank ÷ trip average. */
  liveRangeKm?: number;
  powerKw: number;
  torqueNm: number;
  lambda: number;
  /** Altitude of the route (NaN on a fixed gradient) and the road gradient in %. */
  altitudeM: number;
  gradePct: number;
  t0to100S: number | null;
  t0to100Running: number | null;
  ambientC: number;
  /** Air-cooled engines read their cylinder-head temperature in the coolant field. */
  airCooled: boolean;
  /** Gearbox oil temperature (issue #53, chassis dyno; NaN/unset on the engine dyno) and its warning. */
  gearboxOilC?: number;
  gearboxOilWarn?: boolean;
  /** Tyre hot zone °C (#144, chassis dyno; NaN/unset on the engine dyno), overheating warning, tyre failed. */
  tyreCarcassC?: number;
  tyreWarn?: boolean;
  tyreFailed?: boolean;
  /** Charge-air temperature in the intake manifold, °C, when the core reports it (#83); NaN/undefined = unknown. */
  intakeAirC?: number;
  /** Catalyst temperature, °C (#135, EngineState.catalystC); NaN/undefined = no catalyst. Flag: catalyst heating. */
  catalystC?: number;
  catHeating?: boolean;
  /** Vehicle systems (#83, core vehicle-systems.ts): board-net voltage V, air reservoir bar and its warning, retarder
   *  stage, AdBlue level 0 … 1 and its reserve, lean angle ° (+ left) and whether the tyres could hold it. */
  batteryV?: number;
  airBar?: number;
  airWarn?: boolean;
  retarderStage?: number;
  adblueShare?: number;
  adblueReserve?: boolean;
  leanDeg?: number;
  leanLimit?: boolean;
}

/** What the engine and the dyno can deliver; fields that cannot show anything are skipped while cycling. */
export interface FieldContext {
  turbo: boolean;
  vehicle: boolean;
  /** The core reports the intake air temperature (#83). Until it does, the field is never offered (no faked value). */
  intakeAir?: boolean;
  /** Truck or bus on the chassis dyno: air brake and retarder (#83). */
  commercial?: boolean;
  /** SCR diesel in a vehicle: AdBlue tank (#83). */
  adblue?: boolean;
  /** Motorcycle on a route with curves: lean angle (#83). */
  lean?: boolean;
  /** The engine has a catalyst and the core reports its temperature (#135). */
  cat?: boolean;
}

export function fieldAvailable(id: FieldId, c: FieldContext): boolean {
  switch (id) {
    case "boost": return c.turbo;
    case "range":
    case "road":
    case "gearOil":
    case "tyre":
    case "sprint": return c.vehicle;
    case "intake": return !!c.intakeAir;
    case "air":
    case "retarder": return !!c.commercial;
    case "adblue": return !!c.adblue;
    case "lean": return !!c.lean;
    case "cat": return !!c.cat;
    default: return true;
  }
}

/** Next (dir 1) or previous (dir −1) available field after `cur`; `cur` itself when nothing else is available. */
export function nextField(cur: FieldId, dir: 1 | -1, c: FieldContext): FieldId {
  const n = FIELD_IDS.length;
  const i0 = Math.max(0, FIELD_IDS.indexOf(cur));
  for (let k = 1; k < n; k++) {
    const id = FIELD_IDS[(((i0 + dir * k) % n) + n) % n]!;
    if (fieldAvailable(id, c)) return id;
  }
  return cur;
}

/** The field actually shown for a stored assignment: the stored one, or the next available one after it. */
export function shownField(stored: FieldId, c: FieldContext): FieldId {
  return fieldAvailable(stored, c) ? stored : nextField(stored, 1, c);
}

/** Remaining range from the tank and the trip average (board-computer style), km; NaN without an average. */
export function rangeKm(levelL: number, avgL100: number): number {
  return Number.isFinite(levelL) && Number.isFinite(avgL100) && avgL100 > 0 ? (Math.max(0, levelL) / avgL100) * 100 : Number.NaN;
}

export interface FieldText {
  label: string;
  value: string;
  unit: string;
  /** At or beyond a limit: shown in signal colour. */
  warn: boolean;
}

const NAMES: Record<FieldId, string> = {
  coolant: "Kühlmittel", oilT: "Öltemperatur", gearOil: "Getriebeöl", oilP: "Öldruck", boost: "Ladedruck", egt: "Abgastemperatur",
  fuelNow: "Verbrauch", range: "Reichweite", power: "Leistung", torque: "Drehmoment", lambda: "Lambda", road: "Höhe/Steigung",
  sprint: "0–100 km/h", ambient: "Außentemperatur", intake: "Ansaugluft",
  battery: "Batterie", air: "Druckluft", retarder: "Retarder", adblue: "AdBlue", lean: "Schräglage", cat: "Kat-Temp", tyre: "Reifen",
};

/** Label of a field (no value), e.g. for the accessible name and the settings. */
export function fieldLabel(id: FieldId, u?: UnitPrefs, airCooled = false): string {
  if (id === "coolant" && airCooled) return "Zylinderkopf";
  // the stopwatch measures 0–100 km/h; in mph that is 0–62 mph
  if (id === "sprint" && u?.speed === "mph") return "0–62 mph";
  return NAMES[id];
}

const num = (v: number, d = 0) => (Number.isFinite(v) ? fmt(v, d) : "–");

/** Value, unit and limit flag of one field in the chosen units. */
export function formatField(id: FieldId, v: FieldInputs, u: UnitPrefs, lim?: Partial<EngineLimits>): FieldText {
  const label = fieldLabel(id, u, v.airCooled);
  const T = (c: number) => num(toUnit("temp", c, u.temp));
  const pd = u.pressure === "bar" ? 1 : 0;
  const P = (b: number, d = pd) => num(toUnit("pressure", b, u.pressure), d);
  const out = (value: string, unit: string, warn = false): FieldText => ({ label, value, unit, warn });
  switch (id) {
    case "coolant": return out(T(v.coolantC), u.temp, !v.airCooled && v.coolantC > (lim?.coolantMaxC ?? Infinity));
    case "oilT": return out(T(v.oilC), u.temp, v.oilC > (lim?.oilMaxC ?? Infinity));
    case "gearOil": return out(T(v.gearboxOilC ?? Number.NaN), u.temp, !!v.gearboxOilWarn);
    // tyre (#144): hot-zone temperature, "Platzer" once it has failed
    case "tyre": return v.tyreFailed ? out("Platzer", "", true) : out(T(v.tyreCarcassC ?? Number.NaN), u.temp, !!v.tyreWarn);
    case "oilP": return out(P(v.oilPressureBar), u.pressure, v.running && v.oilPressureBar < (lim?.oilPressureMinBar ?? -Infinity));
    case "boost": return out(P(Math.max(0, v.boostBar), u.pressure === "bar" ? 2 : 1), u.pressure, (lim?.boostMaxBar ?? 0) > 0 && v.boostBar > lim!.boostMaxBar!);
    case "egt": return out(T(v.egtC), u.temp, v.egtC > (lim?.egtMaxC ?? Infinity));
    case "ambient": return out(T(v.ambientC), u.temp);
    case "intake": return out(T(v.intakeAirC ?? Number.NaN), u.temp);
    // catalyst (#135): signal colour while it is still being heated (below light-off)
    case "cat": return out(T(v.catalystC ?? Number.NaN), u.temp, !!v.catHeating);
    case "battery": return out(num(v.batteryV ?? Number.NaN, 1), "V");
    case "air": return out(P(v.airBar ?? Number.NaN, u.pressure === "bar" ? 1 : 0), u.pressure, !!v.airWarn);
    case "retarder": return out(num(v.retarderStage ?? Number.NaN), "Stufe");
    case "adblue": return out(num((v.adblueShare ?? Number.NaN) * 100), "%", !!v.adblueReserve);
    case "lean": {
      const d = v.leanDeg ?? Number.NaN;
      return out(num(Math.abs(d)), Math.abs(d) < 0.5 ? "°" : d > 0 ? "° L" : "° R", !!v.leanLimit);
    }
    case "fuelNow": {
      // per distance while driving, per hour at standstill (like a real board computer)
      if (v.speedKmh > 5) {
        const l100 = v.running ? (v.fuelFlowLh / v.speedKmh) * 100 : Number.NaN;
        return out(num(toUnit("fuel", l100, u.fuel), 1), u.fuel);
      }
      const gal = u.fuel === "mpg";
      return out(num(gal ? v.fuelFlowLh / CONV.lPerGalUs : v.fuelFlowLh, gal ? 2 : 1), gal ? "gal/h" : "l/h");
    }
    case "range": {
      // the same live value as every other range readout; tank ÷ trip average only without it
      const km = Number.isFinite(v.liveRangeKm) ? v.liveRangeKm! : rangeKm(v.tankLevelL, v.avgL100);
      return out(num(toUnit("distance", km, u.distance)), u.distance);
    }
    case "power": return out(num(toUnit("power", Math.max(0, v.powerKw), u.power)), u.power);
    case "torque": return out(num(toUnit("torque", v.torqueNm, u.torque)), u.torque);
    case "lambda": return out(num(v.lambda, 2), "λ");
    case "road": {
      const g = Math.abs(v.gradePct) < 0.05 ? "0" : `${v.gradePct > 0 ? "+" : "−"}${fmt(Math.abs(v.gradePct), 1)}`;
      if (!Number.isFinite(v.altitudeM)) return out(g, "%");
      const alt = u.distance === "mi" ? `${fmt(v.altitudeM * 3.28084)} ft` : `${fmt(v.altitudeM)} m`;
      return out(alt.split(" ")[0]!, `${alt.split(" ")[1]} · ${g} %`);
    }
    case "sprint": {
      const run = v.t0to100Running;
      return out(run !== null ? fmt(run, 1) : v.t0to100S !== null ? fmt(v.t0to100S, 2) : "–", "s");
    }
  }
}

/** Accessible name of a field button: "Feld 1: Öltemperatur – antippen zum Wechseln" (the value is its visible text). */
export function fieldAriaLabel(slot: number, label: string): string {
  return `Feld ${slot + 1}: ${label} – antippen zum Wechseln`;
}

/** Drive-mode word of the sport-saloon display, from the gas response (#66): instant = Sport. */
export function driveModeWord(gasRampS: number): string {
  return gasRampS === 0 ? "Sport" : gasRampS === 1 ? "Normal" : "Eco";
}

/**
 * Intake air temperature from an engine state, °C, or NaN. The core computes the charge-air temperature internally
 * (cycle.ts manifoldTempK) but does not report it yet; this reads `intakeAirC` once the contract carries it (#105).
 */
/** Catalyst temperature from an engine state, °C, or NaN (no catalyst, #135). */
export function catalystOf(s: object): number {
  const v = (s as { catalystC?: unknown }).catalystC;
  return typeof v === "number" && Number.isFinite(v) ? v : Number.NaN;
}

export function intakeAirOf(s: object): number {
  const v = (s as { intakeAirC?: unknown }).intakeAirC;
  return typeof v === "number" && Number.isFinite(v) ? v : Number.NaN;
}
